/**
 * Writes tax / coso / crma / iia / fa agent-authored banks.
 * Run: node scripts/lib/agent-banks/_write-banks-rest.mjs
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const DIR = dirname(fileURLToPath(import.meta.url));

function emit(name, drafts) {
  const exportName = `${name.toUpperCase()}_DRAFTS`;
  writeFileSync(
    join(DIR, `${name}.mjs`),
    `/** Agent-authored ${name} encyclopedia drafts — workplace only. */\nexport const ${exportName} = ${JSON.stringify(drafts, null, 2)};\n`,
    "utf8",
  );
  console.log(name, drafts.length);
}

function t(title, topic, definition, example, trap, formula) {
  return formula
    ? [title, topic, definition, example, trap, formula]
    : [title, topic, definition, example, trap];
}

function expand(specs) {
  return specs.map(([title, topic, mech, example, trap, formula]) =>
    t(title, topic, `${title} ${mech}`, example, trap, formula),
  );
}

